/// <summary>
/// Class used to handle dynamic behavior of dailog during the service execution.
/// </summary>
internal final class METUpdateStockAvailabilitySourceOfSupplyChangeUIBuilder  extends SysOperationAutomaticUIBuilder
{
    private DialogField itemIdDialogField;
    private DialogField inventLocationIdDialogField;
    private DialogField metIntercompanySourcedWarehouseId;
    private DialogField plannedOrderType;
    private DialogField metIntercompanySourced;
    DialogEnumComboBox dialogEnumComboBox;
    private METUpdateStockAvailabilitySourceOfSupplyChangeContract contract;


}

Method.Source:
/// <summary>
/// Method used to handle the behavior of the dialog controls.
/// </summary>
public void postBuild()
{
    super();
    contract = this.dataContractObject() as METUpdateStockAvailabilitySourceOfSupplyChangeContract;
    plannedOrderType = this.bindInfo().getDialogField(contract, methodStr(METUpdateStockAvailabilitySourceOfSupplyChangeContract, parmPlannedOrderTpye));

    Set enumSet = new Set(Types::Enum);
    enumSet.add(ReqPOType::Purch);
    enumSet.add(ReqPOType::Transfer);

    dialogEnumComboBox =  DialogEnumComboBox::newParameters(null,
        plannedOrderType.control().ID(),
        enumNum(ReqPOType),
        enumSet,
        this.dialog().form());

    //plannedOrderType.control().
    plannedOrderType.registerOverrideMethod(methodStr(FormComboBoxControl, modified),
        methodStr(METUpdateStockAvailabilitySourceOfSupplyChangeUIBuilder, plannedOrderTpyeModified),
        this);

    metIntercompanySourcedWarehouseId =  this.bindInfo().getDialogField(contract, methodStr(METUpdateStockAvailabilitySourceOfSupplyChangeContract, parmMetIntercompanySourcedWarehouseId));
    metIntercompanySourcedWarehouseId.registerOverrideMethod(methodStr(FormStringControl, lookup),
        methodStr(METUpdateStockAvailabilitySourceOfSupplyChangeUIBuilder, metIntercompanySourcedWarehouseLookup),
        this);
    metIntercompanySourcedWarehouseId.enabled(false);
    metIntercompanySourced = this.bindInfo().getDialogField(contract, methodStr(METUpdateStockAvailabilitySourceOfSupplyChangeContract, parmMetIntercompanySourced));
    metIntercompanySourced.registerOverrideMethod(methodStr(FormCheckBoxControl, modified),
        methodStr(METUpdateStockAvailabilitySourceOfSupplyChangeUIBuilder, IntercompanySourcedModified),
        this);
}

/// <summary>
/// Constructs lookup for <c>METIntercompanySourcedWarehouse</c> field.
/// </summary>
/// <param name = "_control">
/// <c>FormStringControl</c>.
/// </param>
public void metIntercompanySourcedWarehouseLookup(FormStringControl _control)
{
    InventParameters inventParameters = InventParameters::find();

    Query query = new Query();
    QueryBuildDataSource queryBuildDataSource;
    QueryBuildRange queryBuildRange;

    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation), _control);

    sysTableLookup.addLookupField(fieldNum(InventLocation, InventLocationId));
    sysTableLookup.addLookupField(fieldNum(InventLocation, Name));

    queryBuildDataSource = query.addDataSource(tableNum(InventLocation));

    query.allowCrossCompany(true);
    query.clearCompanyRange();

    if (inventParameters.METInterCompanyPurchaseLegalEntity)
    {
        query.addcompanyRange(inventParameters.METInterCompanyPurchaseLegalEntity);
    }

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

/// <summary>
/// 
/// </summary>
public boolean plannedOrderTpyeModified(FormComboBoxControl _control)
{
    if (_control.valueStr() == enum2Str(ReqPOType::Purch))
    {
        metIntercompanySourced.enabled(True);          

        if (metIntercompanySourced.value() == NoYes::No)
        {
            metIntercompanySourcedWarehouseId.enabled(false);
        }
        else
        {
            metIntercompanySourcedWarehouseId.enabled(true);
        }
    }
    else if (_control.valueStr() == enum2Str(ReqPOType::Transfer))
    {
        metIntercompanySourced.enabled(false);
        metIntercompanySourced.value(NoYes::No);

        metIntercompanySourcedWarehouseId.enabled(false);
        metIntercompanySourcedWarehouseId.value('');
    }

    return true;
}

/// <summary>
/// For Intercompany source modified checkBox enable or disable.
/// </summary>
public boolean IntercompanySourcedModified(FormCheckBoxControl _control)
{
    if (_control.checked() == false)
    {
        metIntercompanySourcedWarehouseId.enabled(false);
        metIntercompanySourcedWarehouseId.value('');
    }
    else
    {
        metIntercompanySourcedWarehouseId.enabled(true);
    }
    return true;
}
